
import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";

const ProjectName = ({
  projectID,
  HandleProjectName,
  projects,
  deviceID,
  isEditable,
  status,
  handleSaveEditClick,
  handleNewProjectClick,
  setProjectName,
  projectName,
}) => {
  const navigate = useNavigate();
  useEffect(() => {
    const selectedProject = projects.find((project) => project.id === projectID);
    if (selectedProject) {
      setProjectName(selectedProject.name)
    }
  }, [projectID, isEditable, projects]);

  const handleEditProjectName = (e) => {
    setProjectName(e.target.value)
  };

  return (
    <div className="row">
      <div className="col-6 col-md-5 col-lg-4 mt-3">
        <h4>Project Information</h4>
      </div>

      <div className="col-6 col-md-7 col-lg-8 d-flex align-items-center">
        <div className="form-floating me-3 flex-grow-1">
          {isEditable ? (
            <input
              type="text"
              className="form-control"
              id="floatingInput"
              value = {projectName}
              onChange={handleEditProjectName}
            />
          ) : (
            <select
              className="form-control"
              id="floatingInput"
              value={projectID}
              onChange={HandleProjectName}
            >
              <option value="">Select a project</option>
              {projects.map((project) => (
                <option key={project.id} value={project.id}>
                  {project.name}
                </option>
              ))}
            </select>
          )}
          <label htmlFor="floatingInput">Project Name</label>
        </div>

        <button
          type="button"
          className="btn btn-primary btn-lg me-2"
          id="NewProject2"
          onClick={() =>
            navigate(`/report/device/${deviceID}/project/${projectID}`)
          }
        >
          Details
        </button>

        <button
          type="button"
          className={`btn btn-lg me-2 ${
            isEditable ? "btn-danger" : "btn-primary"
          }`}
          disabled={status !== "idle"}
          id="NewPr"
          // onClick={() => handleSaveEditClick(editableProjectName)}
          onClick={() => handleSaveEditClick(projectName)}
        >
          {isEditable ? "Save" : "Edit"}{" "}
        </button>

        <button
          type="button"
          className="btn btn-warning btn-lg me-2"
          id="NewProject1"
          disabled={status !== "idle"}
          onClick={handleNewProjectClick}
        >
          +
        </button>
      </div>
    </div>
  );
};

export default ProjectName;
